g=[[9]*20 for _ in range(10)]
pts=[(0,6),(1,17),(2,11),(3,7),(3,15),(4,4),(4,9),(5,3),(5,11),(6,2),(6,9),(7,10),(7,11),(8,12),(8,18)]
for r,c in pts:g[r][c]=1
# Connect consecutive same-row points
for r in range(10):
 cs=sorted(c for rr,c in pts if rr==r)
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b):g[r][c]=3
# Connect consecutive same-column points
for c in range(20):
 rs=sorted(r for r,cc in pts if cc==c)
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b):
   if g[r][c]!=1:g[r][c]=3
print(g)
print('\n'.join(' '.join(map(str,row)) for row in g))
